#define main display_program_main
#include "../udp_rk_rk_yolo/S/x11/csrc/main.cpp"
#undef main
#include <cassert>
struct RawMetadata{int d=-1,b=-1,c=-1;DisplayControlSharedMemory*display=nullptr;EmergencyBrakeSharedMemory*brake=nullptr;CurveDetectionSharedMemory*curve=nullptr;};
static void create(RawMetadata&m,int generation){m.d=shmget(SHM_DISPLAY_CONTROL_KEY,sizeof(DisplayControlSharedMemory),IPC_CREAT|IPC_EXCL|0600);m.b=shmget(SHM_EMERGENCY_BRAKE_KEY,sizeof(EmergencyBrakeSharedMemory),IPC_CREAT|IPC_EXCL|0600);m.c=shmget(SHM_CURVE_DETECTION_KEY,sizeof(CurveDetectionSharedMemory),IPC_CREAT|IPC_EXCL|0600);assert(m.d>=0&&m.b>=0&&m.c>=0);m.display=(DisplayControlSharedMemory*)shmat(m.d,nullptr,0);m.brake=(EmergencyBrakeSharedMemory*)shmat(m.b,nullptr,0);m.curve=(CurveDetectionSharedMemory*)shmat(m.c,nullptr,0);assert(m.display!=(void*)-1&&m.brake!=(void*)-1&&m.curve!=(void*)-1);memset(m.display,0,sizeof *m.display);memset(m.brake,0,sizeof *m.brake);memset(m.curve,0,sizeof *m.curve);m.display->valid=1;m.display->last_update=1;m.display->mode=generation==1?DISPLAY_MODE_PCIE_TOP_RIGHT:DISPLAY_MODE_UDP_BOTTOM_LEFT;m.brake->valid=1;m.brake->person_detected=generation==1;m.brake->brake_enable=generation==1?0:1;m.brake->box_right=120;m.brake->box_bottom=180;m.curve->writer_active=1;m.curve->frame_id=generation==1?42:1;m.curve->curve_type=generation==1?CURVE_LEFT:CURVE_RIGHT;m.curve->confidence=generation==1?91:88;m.curve->curve_angle=generation==1?23:41;}
static void remove_keys(RawMetadata&m){shmctl(m.d,IPC_RMID,nullptr);shmctl(m.b,IPC_RMID,nullptr);shmctl(m.c,IPC_RMID,nullptr);}
static void detach(RawMetadata&m){shmdt(m.display);shmdt(m.brake);shmdt(m.curve);}
static void unit(){MetadataReaders state;uint32_t cursor=7;maintain_metadata_readers(&state,&cursor);assert(!state.curve_available&&!display_control_shm&&!emergency_brake_shm);RawMetadata first;create(first,1);auto expected_display=*first.display;auto expected_brake=*first.brake;auto expected_curve=*first.curve;maintain_metadata_readers(&state,&cursor);assert(!state.curve_available);state.checked_ms=0;maintain_metadata_readers(&state,&cursor);assert(state.curve_available&&state.display_id==first.d&&state.brake_id==first.b&&state.curve_id==first.c&&cursor==UINT32_MAX);assert(display_control_shm->mode==DISPLAY_MODE_PCIE_TOP_RIGHT&&emergency_brake_shm->person_detected==1);uint32_t f,confidence,angle;CurveType type;assert(!curve_detection_read(&f,&type,&confidence,&angle)&&f==42&&type==CURVE_LEFT&&confidence==91&&angle==23);assert(!memcmp(first.display,&expected_display,sizeof expected_display));assert(!memcmp(first.brake,&expected_brake,sizeof expected_brake));assert(!memcmp(first.curve,&expected_curve,sizeof expected_curve));remove_keys(first);RawMetadata second;create(second,2);cursor=1;state.checked_ms=0;maintain_metadata_readers(&state,&cursor);assert(cursor==UINT32_MAX&&state.display_id==second.d&&state.brake_id==second.b&&state.curve_id==second.c);assert(display_control_shm->mode==DISPLAY_MODE_UDP_BOTTOM_LEFT&&emergency_brake_shm->person_detected==0&&emergency_brake_shm->brake_enable==1);assert(!curve_detection_read(&f,&type,&confidence,&angle)&&f==1&&type==CURVE_RIGHT&&confidence==88&&angle==41);remove_keys(second);state.checked_ms=0;maintain_metadata_readers(&state,&cursor);assert(!state.curve_available&&!display_control_shm&&!emergency_brake_shm&&current_curve_type==CURVE_NONE&&current_curve_confidence==0);assert(second.display->valid==1&&second.brake->valid==1&&second.curve->writer_active==1);detach(first);detach(second);puts("METADATA_LATE_START_GENERATION_READER_ONLY_PASS");}
int main(int argc,char**argv){if(argc>1){int generation=atoi(argv[1]);RawMetadata metadata;create(metadata,generation);metadata.display->mode=DISPLAY_MODE_ALL_CAMERAS;SharedMemoryManager p={},u={};assert(!shared_memory_init(&p,SHM_TYPE_PCIE,1));assert(!shared_memory_init(&u,SHM_TYPE_UDP,1));std::vector<uint16_t>a(640*480,generation==1?0xf800:0x001f),b(640*480,generation==1?0xf800:0x07e0);for(int n=0;n<60;++n){assert(!shared_memory_write_image(&p,(uint8_t*)a.data(),640,480));assert(!shared_memory_write_image(&u,(uint8_t*)b.data(),640,480));usleep(50000);}shared_memory_cleanup(&p);shared_memory_cleanup(&u);remove_keys(metadata);detach(metadata);return 0;}unit();}
